def compute(vars):
    start = vars["v1"]
    end = vars["v2"]

    if start == 0:
        return None

    change_ratio = (end - start) / start
    percentage_change = change_ratio * 100

    return {
        "value": percentage_change,
        "trace": {
            "start_balance": start,
            "end_balance": end,
            "change": end - start,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
